-- ----------------------------------------------------------------
-- Quests take the query-reply values of the retail 15595 sniffs, objectives
-- aside.
--
-- The values are the quest query reply's fields from the Cataclysm
-- Preservation Project's world database (rows verified on build 15595),
-- which agree with retail client caches of builds 13623 and 14480. The
-- money a max-level player gets instead of experience is what the client
-- shows in the quest log (the larger of it and the reward money); ours paid
-- up to ten times the retail amount. Left for later: objectives, whose new
-- targets need their credit checked, and the money of level -1 quests,
-- whose sniffed value follows the sniffing character's level.
-- ----------------------------------------------------------------
DROP PROCEDURE IF EXISTS `update_mangos`;

DELIMITER $$

CREATE PROCEDURE `update_mangos`()
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SHOW ERRORS;
        SELECT '* UPDATE FAILED *' AS `===== Status =====`,
               @cCurResult AS `===== DB is on Version: =====`;
        RESIGNAL;
    END;

    SET @cCurVersion := (SELECT `version` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurStructure := (SELECT `structure` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cCurContent := (SELECT `content` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);

    SET @cOldVersion = '22';
    SET @cOldStructure = '11';
    SET @cOldContent = '009';

    SET @cNewVersion = '22';
    SET @cNewStructure = '11';
    SET @cNewContent = '010';
    SET @cNewDescription = 'Quest_Query_Values';
    SET @cNewComment = 'Quests take the query-reply values of the retail 15595 sniffs, objectives aside';

    SET @cCurResult := (SELECT `description` FROM `db_version` ORDER BY `version` DESC, `structure` DESC, `content` DESC LIMIT 0,1);
    SET @cOldResult := (SELECT `description` FROM `db_version` WHERE `version` = @cOldVersion AND `structure` = @cOldStructure AND `content` = @cOldContent);
    SET @cNewResult := (SELECT `description` FROM `db_version` WHERE `version` = @cNewVersion AND `structure` = @cNewStructure AND `content` = @cNewContent);

    IF (@cCurResult = @cOldResult) THEN
        START TRANSACTION;

        UPDATE `quest_template` SET `Details` = 'The once swift Shadumbra now lies still as you claim victory over it.$b$bThis legenday creature is dear to the night elves. Its head should serve as an intimidating trophy, and as a sign of the end of the Alliance in Ashenvale.$b$bCaptain Goggath at Hellscream''s Watch will no doubt be delighted to receive the head of the slain nightsaber.' WHERE `entry` = 24;
        UPDATE `quest_template` SET `NextQuestInChain` = 0 WHERE `entry` = 32;
        UPDATE `quest_template` SET `NextQuestInChain` = 0 WHERE `entry` = 162;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 1740 WHERE `entry` = 193;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 1320 WHERE `entry` = 196;
        UPDATE `quest_template` SET `Details` = 'The Thistlefur furbolgs are threatening our expansion!  Thistlefur Village to our west blocks the way between us here and the Splintertree Post.  It''s a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path.$B$B$N, we must not allow... an expansion path gap!$B$BProceed to Thistlefur Village and thin out the furbolgs.  You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!' WHERE `entry` = 216;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 330 WHERE `entry` = 264;
