        UPDATE `quest_template` SET `Details` = 'I see a lot of young dwarves at my door, eager to learn the trade of cooking.  And if there''s one thing a cook needs more than anything, it''s a cleaver!$B$BI have a list of students who scored high in their lessons and earned an honorary cleaver.  Take my list to Golnir Bouldertoe in Ironforge.  He''ll get the cleavers ready.$B$BThe fastest way to Ironforge is on a gryphon, so bring the list to our gryphon master, Brolan Galebeard, and speak with him about transport to Ironforge.' WHERE `entry` = 6387;
        UPDATE `quest_template` SET `Details` = 'Here are the honorary cleavers for Gremlock''s students.  If you''ve already been to Kharanos, then you should fly a gryphon back there!$B$BTake the cleavers to our gryphon master, Gryth Thurden, and speak with him about a ride back to Kharanos.' WHERE `entry` = 6388;
        UPDATE `quest_template` SET `Details` = 'For just a few coins, one of my gryphons will take you to Ironforge.  From there, deliver Gremlock''s list to Golnir Bouldertoe.  You''ll find him in the Deep Mountain Mining Guild.  That''s in the Great Forge District of Ironforge, which is right where my gryphon will drop you off!$B$BSpeak to me again when you''re ready for the journey.' WHERE `entry` = 6391;
        UPDATE `quest_template` SET `Details` = 'For a small fee you can buy a gryphon ride to Kharanos... as long as you''ve already been there.  Gryphons will only fly you to places you''ve already been, so be sure to speak with every gryphon master you see so you can fly to him later.$B$BYou''ve already been to Brolan, the gryphon master of Kharanos, so now you can return to him.  And once in Kharanos, you can deliver the cleavers to Gremlock Pilsnor.$B$BSpeak with me when you''re ready to go.' WHERE `entry` = 6392;
        UPDATE `quest_template` SET `Details` = 'My kinfolk were traveling here with many sacred troll charms, but the Thistlefur furbolgs attacked and killed them before they reached Zoram''gar!  Those vile furbolgs!$B$BI miss my brothers and sisters who were killed, but we will meet again in the afterlife.  However, their troll charms hold great value in this world.  It is an outrage that the furbolgs have them!$B$B$N, you must retrieve the charms!  They are in chests in Thistlefur Hold, a cave at the end of Thistlefur Village, north of Astranaar.' WHERE `entry` = 6462;
