        UPDATE `quest_template` SET `Type` = 0, `SuggestedPlayers` = 0, `Details` = 'You''ve figured out how to use the single-person relics, but as you may have seen, there are bigger ones, which they surround.$B$BThese larger apexis monuments function in much the same way, but they take 35 apexis shards to activate.$B$BOf greater concern to us are the guardians that are summoned through their use.  These crystal constructs turned on their arakkoan masters long ago, and now endanger Ogri''la.$B$BWe would ask that you destroy one and bring us proof.' WHERE `entry` = 11059;
