        UPDATE `quest_template` SET `Type` = 0, `SuggestedPlayers` = 0, `Details` = 'As ye''ve flown around, ye must have noticed the dragons above.  I trust ye haven''t fallen victim ta their rage.  Help us put an end ta it, $N!$B$BRivendark and Obsidia lord over this terrace, while Insidion and Furywing rule the skies over yon terrace ta the northeast.  Each has a perch on their respective domains.  I be wondering if ye and yer friends will go ta one, $g lad : lass;, break open an egg with 35 apexis shards and attract the dragon down.$B$BBring me some teeth as proof.' WHERE `entry` = 11078;
        UPDATE `quest_template` SET `Type` = 0, `SuggestedPlayers` = 0, `Details` = 'Gahk think being smart is dumb sometimes.  Gahk not want to think.  Me want little $r to smash big demons!$B$BDey have some chiefs, and da chiefs all have whips to hurt da little demons.  You bring Gahk a whip!$B$BYou challenge demon chief in forge camps at burning, green, fel crystal prism.  Use 35 apexis shards to get dem to come.  Dey called Galvanoth, Braxxus, Zarcsin and da Mo''arg Incinerator.' WHERE `entry` = 11079;
