        UPDATE `quest_template` SET `Type` = 0, `SuggestedPlayers` = 0, `Details` = 'You were right to bring this to me, $N. You must venture to Gjalerbron and slay that wyrm and its master, Wyrmcaller Vile!$B$BEven now, as we speak here, the frost wyrm may be on its way.$B$BHowever, if I''m reading these plans correctly, blowing the wyrmcaller''s horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!$B$BAnd $N, please bring me the horn. We wouldn''t want it falling back into the wrong hands.' WHERE `entry` = 11238;
