        UPDATE `quest_template` SET `Details` = 'Archmage Berinand loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble.$B$BI made the mistake of discussing it with a group of Horde adventurers and now it''s gone!$b$bIt must have been them. Please, recover the book.', `Objectives` = 'Image of Warmage Kaitlyn wants you to recover Berinand''s Research.', `CompletedText` = 'Return to Image of Warmage Kaitlyn in the Nexus.', `RewMoneyMaxLevel` = 24000 WHERE `entry` = 13094;
