        UPDATE `quest_template` SET `Details` = 'Malygos and his underlings grow stronger in power with each passing day. And now, our latest assault team has been captured and is being held in the Oculus.$b$bWe must attempt a rescue! Belgaristrasz and his companions are invaluable to our cause.', `Objectives` = 'Raelorasz wants you to rescue Belgaristrasz and his companions in the Oculus.' WHERE `entry` = 13124;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 156900 WHERE `entry` = 13125;
        UPDATE `quest_template` SET `Details` = 'From here, it will take our combined efforts to proceed.$b$bAbove us, Varos hides behind an impenetrable shield. To reach him, you must defeat the Centrifuge Constructs that power his shield.$b$bWe can each provide you with drakes from our respective flights to help you reveal him.' WHERE `entry` = 13126;
        UPDATE `quest_template` SET `Details` = 'Only one obstacle stands between us and our ultimate goal here. His name is Urom.$b$bHe guards the third ring above us. Beware his powerful conjurings, friend.$b$bBring him down. Make him pay for his treacherous allegiance to the enemy!' WHERE `entry` = 13127;
        UPDATE `quest_template` SET `Details` = 'The time has come to face Eregos.$b$bHe draws strength from the energies he is charged with defending - sipping from the well of the great aspect Malygos.$b$bHowever, defeating the Mage-Lord has allowed us to unlock the full power of our drakes. Use them wisely and Eregos shall surely fall.', `Objectives` = 'Belgaristrasz wants you to kill Eregos in the Oculus.', `CompletedText` = 'Return to Image of Belgaristrasz inside the Oculus.' WHERE `entry` = 13128;
        UPDATE `quest_template` SET `Details` = '<Kurzel rips a long strip of material from her blouse and hands it to you.>$b$bHere, $r, take this. Dip it in the remains of Novos the Summoner.$b$bWe''re going to figure out what makes the Scourge leaders tick.', `Objectives` = 'Kurzel wants you to use Kurzel''s Blouse Scrap at the corpse of Novos the Summoner, then take the Ichor-Stained Cloth to her inside Drak''Tharon Keep.', `CompletedText` = 'Return to Kurzel inside Drak''Tharon Keep.', `RewMoneyMaxLevel` = 24900 WHERE `entry` = 13129;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 104700 WHERE `entry` = 13130;
        UPDATE `quest_template` SET `RewXPId` = 7, `Details` = 'Just look at it! Me trunk never been so empty.$b$bMe mates jumped at the sight o'' all that booty, and now look at ''em! Rattlin'' bones, they be!$b$bSay, thar be plenty o'' loot farther in, an'' not the cursed kind I''ll wager.$b$bFetch it fer me an'' I''ll be rewardin'' ya handsomely, matey.\n', `RewOrReqMoney` = 222000, `RewMoneyMaxLevel` = 198600 WHERE `entry` = 13131;
        UPDATE `quest_template` SET `Details` = 'Only luck spared me from the same fate as me mates.$B$BIn the scurry I got knocked down - was a wee bit tipsy to begin with. Looked up ta see the first of ''em turn.$b$bThere was a big ol'' fella watchin'' with a whole mess o'' guards. They were chantin'' Ymiron... maybe killin'' him will free me mates?' WHERE `entry` = 13132;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 104700 WHERE `entry` = 13135;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 104700 WHERE `entry` = 13139;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 104700 WHERE `entry` = 13141;
        UPDATE `quest_template` SET `Details` = 'The infinite dragonflight seek to disrupt history by deceiving Prince Arthas.$b$bIf they can convince him that none of the grain here carries the plague, then he''ll never have to make the fateful decision to cull Stratholme.$b$bUse this arcane disruptor on any suspicious crates of grain you find.' WHERE `entry` = 13149;
        UPDATE `quest_template` SET `Details` = 'Arthas will soon face a desperate dilemma, and make a momentous decision.$b$bI must call upon you to accompany the prince in his culling.$b$bArthas must make it through Stratholme alive and you must see to it that he defeats Mal''Ganis!' WHERE `entry` = 13151;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 156900 WHERE `entry` = 13157;
        UPDATE `quest_template` SET `Details` = 'In my peoples'' struggle against the forces of the undead, they dug deeper as they lost ground.$b$bThey inadvertently exposed minions of the Old Gods known only as the Faceless.$b$bIn the end, we could not fight a war on two fronts.$B$BWith your aid, perhaps the Faceless will finally fall.', `Objectives` = 'Seer Ixit in Ahn''Kahet wants you to kill Herald Volazj and the three Forgotten Ones that accompany him.', `CompletedText` = 'Return to Seer Ixit in Ahn''Kahet.', `RewMoneyMaxLevel` = 50700 WHERE `entry` = 13187;
        UPDATE `quest_template` SET `Details` = 'We must discover the secret to these savages'' weapons!$b$bIf you''d have seen how easily they cut through my companions, you''d understand my sense of urgency.$b$bScour the place. Gather all of their arms that you can carry.', `Objectives` = 'Dark Ranger Marrah wants you to steal 5 Vrykul Weapons from Utgarde Keep and bring them to her inside Utgarde Keep.', `CompletedText` = 'Return to Dark Ranger Marrah inside Utgarde Keep.', `RewMoneyMaxLevel` = 24000 WHERE `entry` = 13206;
        UPDATE `quest_template` SET `Details` = 'Well now, I''m surprised to see other adventurers in a place such as this.$b$bIf my research on these halls is accurate, there be monumental discoveries to be made here!$b$bAssumin'' I can count on ya to watch my back, you''re welcome to tag along.', `CompletedText` = 'Return to Brann Bronzebeard in the Halls of Stone.' WHERE `entry` = 13207;
