        UPDATE `quest_template` SET `Details` = 'Just in time, $c. The elves have launched another attack!$b$bFrom the guard towers, use the accursed ore to mark targets for Draaka.$b$bHer projectiles will strike your target and erupt in fel magic flame, destroying any nearby enemies.$b$bThere is strong prejudice against the use of demonic magics. Unjustified, but real nonetheless. For this reason, I will transform you into an imp for the duration of the mission to prevent you from being identified.' WHERE `entry` = 13798;
