        UPDATE `quest_template` SET `Details` = 'I''m definitely on to something here!$b$bI have enough volatile elements salvaged from our arsenal to make the explosives Goggath wants, but I need to stabilize it and pack it into bombs.$b$bWhat I need is some clay - and not just any clay... moon-kissed clay.$b$bIt''s only found on the northern banks of Astranaar Lake, and it possesses the qualities I need to bring out the full potential of my discovery!', `Objectives` = 'Tweedle at Hellscream''s Watch wants you to collect 10 samples of Moon-Kissed Clay.' WHERE `entry` = 13942;
