        UPDATE `quest_template` SET `Details` = '<Rocco hands you a familiar-looking shotgun.>$B$BI took the liberty of cleaning up Halga''s artillery for you. I''m sure I don''t need to warn you about the kickback. Just ask me when you''re ready to mount up for the Crossroads! Thork is waiting for you there. Be sure not to give him any lip.$B$BDon''t stop for nothing, $N, and if someone gets too close, just give ''em a thump with the butt-end of your gun. Do us proud!', `Objectives` = 'Talk to Rocco Whipshank at Grol''dom Farm and escort his caravan all the way to the Crossroads.' WHERE `entry` = 13975;
