        UPDATE `quest_template` SET `Details` = 'Here it is - the Hand of Iruxos.$b$bGot it from one o'' them Burning Blade leaders myself.$B$BPowerful thing! See, yeh use it on demon portals and they just disappear! Spooky magic, but these be desperate times...$b$bThe demons keep comin'' at this rate, and my camp will get overrun before ya know it.$b$bHere ya go, now. Get on with it.' WHERE `entry` = 14374;
