        UPDATE `quest_template` SET `Details` = 'They''ve put our captured soldiers to work in the quarry!$B$BKill their captors and set them free, hero. We will need their aid when we confront Scourgelord Tyrannus.' WHERE `entry` = 24498;
        UPDATE `quest_template` SET `Details` = 'We''re severely undermanned to be risking a venture into the citadel, but opportunities like this are too rare to pass up.$B$BClear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the citadel.' WHERE `entry` = 24499;
        UPDATE `quest_template` SET `Details` = 'It''s hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?$B$BMany questions remain. but you need to find Jaina and escape the Lich King while there''s still time.', `Objectives` = 'Find Lady Jaina Proudmoore and escape the Halls of Reflection.' WHERE `entry` = 24500;
