        UPDATE `quest_template` SET `Details` = 'We need to make our way up the main path and through the cave to Tyrannus'' rise.$B$BHe will be forced to confront us there lest we make our way into the citadel proper.$B$BGo now, $c. My men and I will be there to stand by you when the confrontation with Tyrannus comes.' WHERE `entry` = 24710;
        UPDATE `quest_template` SET `Details` = 'We must press on, hero. We''ve come so far... we''re so close to our goal.$B$BI must delay a moment to send Elandra back to the airship. I''m uncertain how we''re going to escape with so many men lost and so few to keep our path in secure.$B$BContinue on. I will meet you in the Halls of Reflection. ' WHERE `entry` = 24711;
        UPDATE `quest_template` SET `Details` = 'We need to make our way up the main path and through the cave to Tyrannus'' rise.$B$BThere, he will be forced to confront us there lest we make our way into the citadel proper.$B$BGo now, $c. My men and I will be there to stand by you when the confrontation with Tyrannus comes.' WHERE `entry` = 24712;
        UPDATE `quest_template` SET `Details` = 'Keep moving, the sword is close.$B$BI need a moment to send one of my dark rangers back to the airship. With all of our fodder gone, I will not be caught unprepared - we will need any help they can send.$B$BGo. I will meet you in the Halls of Reflection. ' WHERE `entry` = 24713;
