        UPDATE `quest_template` SET `Details` = 'Now that I know you''re not squeamish, I''ve got another job for you. Have you seen the red-feathered birds swarming around the bones out there? Those are fire rocs. They''ll light you up good if you''re not careful.$B$BThey''re also pretty darn valuable thanks to their unique anatomy. Most of the hunters loafing around here aren''t up to the task of killing fire-spitting buzzards for money... think you can handle it?', `RewMoneyMaxLevel` = 4200 WHERE `entry` = 25111;
