        UPDATE `quest_template` SET `Details` = 'The actions of these feral dogs are beginning to make sense. The Twilight''s Hammer fears the power of the ancients. They do not want Lo''Gosh to return.$B$BSo they''ve summoned their own wolf god - a perversion of what once was. "Lycanthoth," the corruptor.$B$B$N, Lycanthoth is but a shadow of Lo''Gosh''s power, but the beast must be destroyed so that the true ancient can return. Take this incense, and burn it in the Maw of Lycanthoth east of here. Slay the monstrosity and free the spirit of Lo''Gosh!', `CompletedText` = 'Speak with the Spirit of Lo''Gosh in front of Lycanthoth''s Altar at the Maw of Lycanthoth in Mount Hyjal.', `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25272;
