        UPDATE `quest_template` SET `Details` = '<Ysera''s eyes look distant, as if not fully acknowledging you.>$B$BI feel it as well, $c. Ragnaros has arrived.$B$BWe must defeat his minions before he can join them and lend them his strength.$B$BSeek Malfurion Stormrage at the Tranquil Grove, west of here, and aid his forces in any way you can.$B$BI must seek answers from within the Emerald Dream.  You must protect the World Tree until I return.', `RewMoneyMaxLevel` = 16550 WHERE `entry` = 25317;
        UPDATE `quest_template` SET `Details` = 'Make no mistake about this, $N.  The outcome of this war will determine the very survival of our world as we know it.$B$BThe Twilight''s Hammer has become more powerful than ever with Deathwing''s return.  Should they succeed in taking over the World Tree, they might strike a blow from which we will never recover.$B$BIt is time we beat back the enemy.  It is time we crushed the Twilight''s Hammer.', `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25319;
