        UPDATE `quest_template` SET `Details` = 'When I prayed at the shrine, Goldrinn granted me another vision. I saw you standing astride the Lightning Ledge, with lightning in your hands. Goldrinn seems to feel that this is of the utmost importance, but I don''t understand what the ancient has planned...$B$B$N, go to the Lightning Ledge. Twilight''s Hammer has been running experiments with something called a "Lightning Channel." Investigate these channels, then use this totem to summon the Spirit of Goldrinn and see what he has in mind... ', `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25353;
        UPDATE `quest_template` SET `Details` = 'The shrine is secure, the ogres in disarray. Enough. The time has come to go on the offensive.$B$BSomething sinister is underway above us, on the Lightning Ledge. It is time to unleash the fury of the ancients!$B$BFly up to the Lightning Ledge and demolish the Twilight''s Hammer there. Crush them, $N, slay their creations and hurl their bodies from the mountainside!' WHERE `entry` = 25354;
        UPDATE `quest_template` SET `Details` = 'Lo''Gosh granted me a vision while you were in the hovel, $N. I saw you striding across the Lightning Ledge, with lightning bolts in your hand. The vision was powerful: Lo''Gosh feels this is of utmost importance. We must not fail the ancient.$B$BUpon the Lightning Ledge, Twilight''s Hammer has been experimenting with devices they call "Lightning Channels."$B$BInvestigate one of these channels, then use this totem to summon the Spirit of Lo''Gosh and learn what the ancient is planning...' WHERE `entry` = 25355;
