        UPDATE `quest_template` SET `Details` = 'This is no mere natural occurrence, $N.  There must be a twilight presence behind our lines that we haven''t accounted for.$B$BIt''s possible that whoever is instigating the elemental disturbance is using foul magic to hide themselves from our sight.$B$BSeek the aid of the faerie dragons that roam near the World Tree; they can see through any of our enemy''s illusions.$B$BFeed them the juniper berries that grow nearby to gain their trust.', `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25370;
