        UPDATE `quest_template` SET `Details` = 'You''ve got to help us, $glad:lass;. We were tasked with escorting a precious cargo to our fellow dwarves...a keg full of the finest ale you can get out here!$B$BUnfortunately, bird-brain over here fell asleep on the job! Those blasted orcs took our keg, and hauled it up into Dun Algaz where they''re hiding.$B$BThis can''t stand! Now, while I stay here and try to convince this idiot that it was his fault, I''d like you to go in there and get our keg back. For Khaz Modan!', `RewMoneyMaxLevel` = 960 WHERE `entry` = 25395;
