        UPDATE `quest_template` SET `Details` = 'This is going to take a while, but I''m sure we''ll beat them back.$B$BYou''re more good to Thousand Needles elsewhere. We have reports that the gnomes and goblins out on the flooded salt flats somehow survived on a giant barge! Rendow is on the dock. She''ll get you a boat to go there.$B$BMind helping us out a little on your way to her?' WHERE `entry` = 25486;
        UPDATE `quest_template` SET `Details` = 'Are you ready to go, $c?$B$BOne of our braves will row you out to the Mirage Raceway. If anyone has survived out there, they''ll desperately need your help.$B$BMay the Earth Mother smile upon you.', `RewMoneyMaxLevel` = 660 WHERE `entry` = 25489;
        UPDATE `quest_template` SET `Details` = '$N, these fiends from the Twilight''s Hammer are attempting to scourge this whole mountain clean of all life. Even now they trail behind this inferno, leaving death and ash in their wake.$B$BArch Druid Hamuul Runetotem is behind the fires, trying to salvage the wilderness before it''s blotted permanently from the map. Travel southeast, through The Inferno and down the road beyond. Find and aid the Arch Druid.$B$BOn your way there, clear the roads by killing any Charbringers that you find.', `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25490;
        UPDATE `quest_template` SET `Details` = 'This land has been scourged by fire, but it may yet renew itself.$B$BSome seeds deep in the soil may have withstood the scorching heat here in The Flamewake. These durable plants are the key to this forest''s regrowth. Please, collect some of these seedlings for me.', `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25491;
