        UPDATE `quest_template` SET `Details` = 'Here we go. This is the speech, $N!$b$bIt has everything to be a great battle starter: It''s inspirational, has eloquent language and speaks directly to gnomes. Never has a finer speech been written!$b$bTurn this in to Captain Tread Sparknozzle and see if there''s anything else he needs of you.' WHERE `entry` = 25500;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25502;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25503;
        UPDATE `quest_template` SET `Details` = 'Fresh and stinking, these innards will prove to be irresistible for Nemesis, the befouled turtle god created by Twilight''s Hammer.$B$BNemesis must eventually be destroyed, but first, we must collect a piece of his fiery armored shell. With it, we''ll be able to work some magic to free the true ancient.$B$BGo into the Flamewake and drop this bait near Nemesis. It will distract him. Pry off a piece of his shell... then run, if you hope to survive the encounter.', `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25507;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25509;
        UPDATE `quest_template` SET `Details` = '<The Arch Druid fills the shell fragment with water, which boils instantly. He adds a bundle of herbs and closes his eyes in a silent prayer.>$B$B$N, Tortolla the turtle ancient is ageless, a part of this world since the time of the titans. He speaks a language older than our understanding.$B$BDrink this and find a place of calm within yourself. You will be able to understand the language of Tortolla. Go to him now, in the Ashen Lake. Earn the ancient''s trust. The fate of Hyjal hinges on this. ', `RewMoneyMaxLevel` = 6600 WHERE `entry` = 25510;
