        UPDATE `quest_template` SET `Details` = 'Without any defenders, the Firelands eggs are vulnerable.$B$BTake wing once more and smash those eggs! Simply rush over them to crush them. Search all the nooks, crannies, and side-caves. Hurry! ' WHERE `entry` = 25560;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 3900 WHERE `entry` = 25565;
        UPDATE `quest_template` SET `Details` = 'I studied these ruins for years trying to find a way in. We even took a good chunk out of the gate, only to find impenetrable walls beneath. Now the cataclysm may''ve wrecked everything in there something fierce, but it''s done what we couldn''t and opened a way in!$B$BI''d like you to have the honor, $Glad:lass;. Head on in there and see if anything''s been left uncracked. Be careful though... there''s no telling what, or who, might be stirring in there.', `RewMoneyMaxLevel` = 3900 WHERE `entry` = 25566;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25574;
        UPDATE `quest_template` SET `Details` = 'The weapons the Twilight''s Hammer uses against us are crafted by Forgemaster Pyrenduis within these very halls. The metal slices through armor like cheese in the hands of its wielder. Yet, when captured, the steel turns brittle and shatters.$B$BSo be it, $N. I''d rather see those cursed arms smashed than delivered to our enemy.$B$BSeek out the crates of Twilight arms in these caverns and smash them to pieces.', `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25575;
        UPDATE `quest_template` SET `Details` = 'Here we are deep within the realm of the fire god and what do we find? The little puppets of Ragnaros, scurrying around to do his bidding.$B$BThese Dark Iron laborers are finishing and packaging the weapons Twilight''s Hammer hopes to use in their conquest of Hyjal. I don''t care if they''re here of their own free will or if they''ve been brainwashed or kidnapped... They''re a foe of our beloved wolf ancient and they should pay the ultimate price.', `RewMoneyMaxLevel` = 66000 WHERE `entry` = 25576;
