        UPDATE `quest_template` SET `Details` = 'The local wildlife''s all messed up from the flood, it seems. This fen used to be full of crocolisks, but I haven''t spotted a single one.$B$BWhat I have spotted are threshadons. Never used to be any here, so the flood must''ve swept them all right out of Loch Modan.$B$BLucky for us, because they''re tastier than crocolisks, and I''m running low on provisions. Bring me back some threshadon meat for the camp, and I''ll gladly pay you for it.' WHERE `entry` = 25723;
