        UPDATE `quest_template` SET `Details` = 'It''s funny. Kin and I have been through so much together, and here we find ourselves back in Arathi, like so many years ago.$B$BWe broke up a plot to create a new plague right here, her and I. It doesn''t look like the Horde learned their lesson, because they''re all over this farm yet again.$B$BTheir undead courier is shuffling around as obvious as daylight. If you want to help, find the courier and bring back whatever they''re carrying.', `RewMoneyMaxLevel` = 2040 WHERE `entry` = 26110;
        UPDATE `quest_template` SET `RewMoneyMaxLevel` = 104000 WHERE `entry` = 26111;
        UPDATE `quest_template` SET `Details` = 'The Horde have held Go''shek Farm to the east for a long time; it''s never been of much concern compared to the rest of our problems here. But there''s been reports of undead activity in the area.$B$BAnything more alarming than shuffling peons over there warrants investigation. This isn''t the first time the undead have been up to no good at the farm, so I''ve sent my best scouts there to check it out. Report to Quae and Kinelory and they''ll fill you in.' WHERE `entry` = 26113;
