        UPDATE `quest_template` SET `Details` = 'As you know, $N, Garrosh has relegated the trolls of Orgrimmar to the western outskirts of the city.  Fortunately, that means that we have easy access to their supplies.  I am working on a large batch of jambalaya for the infantry and I need as much rice as possible.  Lucky for us, the trolls keep it stored in barrels near their structures.  Retrieve these barrels of Darkspear rice for me and I should be able to finish up. ' WHERE `entry` = 26233;
