        UPDATE `quest_template` SET `Details` = 'The scrolls are vague and appear to be a piece of a much larger puzzle, but if you are not mistaken, they seem to reveal some of the steps on the path to becoming a demon hunter.$B$BThe dark oaths and rituals necessary for becoming a demon hunter are frowned on by most of the night elves, so this is likely something they would be very interested in keeping quiet.$B$BRanger Glynda Nal''Shea will know what to do with these scrolls.' WHERE `entry` = 28529;
        UPDATE `quest_template` SET `Details` = 'The cauldron looked like it contained concentrated material. If the Winterfall are diluting this stuff directly in the springs, contamination could build up over time... and then the dilution would be less and less effective.$B$BThe spring to the northeast has boiled over with elementals. I thought it was because of the cataclysm, but their appearance could be a reaction to this.$B$BCould you check them for corruption? Hunt a few and bring me any bits of green foreign material they leave behind.' WHERE `entry` = 28530;
