        UPDATE `quest_template` SET `Details` = 'Sometimes fishing means throwing something back, $c.$b$bWe''ve been overfeeding these frogs for just that occasion.  We''ve fed these frogs bloated spiders, that were fed bloated flies, and now, we are going to feed a real monster.$b$bThe moat above, in the Ruins of Lordaeron, is home to our very own moat monster.$b$bToday is feeding day.  But we must train it as well.  In this bag, you will find a decoy kit and some bloated frogs.  Use the decoy kit, then toss the frogs to the monster when it appears.' WHERE `entry` = 29361;
        UPDATE `quest_template` SET `Details` = 'A holiday sweater may not be for everyone.$b$bThe receipt says that you can exchange it for gold at any Smokywood Pastures merchant.$b$bAll exchanges are final.', `Objectives` = 'If you truly dislike your present, you can exchange it for gold by speaking to a Smokywood Pastures merchant.$b$bAll exchanges are final.', `EndText` = 'You may exchange your sweater for gold at a Smokywood Pastures merchant.  All exchanges are final.' WHERE `entry` = 29382;
