        UPDATE `quest_template` SET `Details` = 'The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands.$B$BWilling and able-bodied heroes of the Alliance should report to the Sanctuary of Malorne in Mount Hyjal immediately.' WHERE `entry` = 29387;
        UPDATE `quest_template` SET `Details` = 'The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist with a full-scale assault on the Firelands.$B$BWilling and able-bodied champions of the Horde should report to the Sanctuary of Malorne in Mount Hyjal immediately.' WHERE `entry` = 29388;
        UPDATE `quest_template` SET `Details` = 'Your work has given us the advantage we need to mobilize against the denizens of the Firelands. We are gathering our invasion force just south of our position.$B$BWe could use your strength again, $r. Speak with Matoclaw at the Sanctuary of Malorne. She is coordinating the invasion effort.' WHERE `entry` = 29389;
        UPDATE `quest_template` SET `Details` = 'The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist in defending Mount Hyjal from elemental invaders. These invaders must be repelled before forces can mobilize for a direct assault on the Firelands.$B$BWilling and able-bodied heroes should report immediately to Mount Hyjal and assist the ancient defenders: Lo''gosh, Tortolla, Aviana, and Aessina.$B$BNew travelers to Mount Hyjal may look for a Warchief''s Command to Hyjal on any Horde call board.' WHERE `entry` = 29390;
        UPDATE `quest_template` SET `Details` = 'The Guardians of Hyjal, led by Arch Druid Malfurion Stormrage, seek brave heroes to assist in defending Mount Hyjal from elemental invaders. These invaders must be repelled before forces can mobilize for a direct assault on the Firelands.$B$BWilling and able-bodied heroes should report immediately to Mount Hyjal and assist the ancient defenders: Goldrinn, Tortolla, Aviana, and Aessina.$B$BNew travelers to Mount Hyjal may look for a Hero''s Call to Hyjal on any Alliance board.' WHERE `entry` = 29391;
        UPDATE `quest_template` SET `Details` = '<sigh>$b$bDon''t talk to me about last year''s stein...$b$bI think our shady stein suppliers were somehow involved with that Twilight Hammer cult non-sense that errupted just before the elementals invaded.$b$bAnd that''s why we have a new supplier and a better stein!$b$bHere''s a voucher for one.$b$bTalk to Blix near the back of the Brewfest camp.  He''s pretty strange, even more so now that he''s always wearing those goggles.  He''ll handle the voucher for you, and any other Brewfest transaction.' WHERE `entry` = 29396;
        UPDATE `quest_template` SET `Details` = 'Please, $gmister:miss;, you just gotta help me!$b$bMy pa brought me a bunch of balloons from the Darkmoon Faire. Best... gift... EVER! They''re magical, you know, and never lose their floatiness!$b$bThere''s just one thing...$b$bA big ol'' gust of wind blew ''em right outta my hands. They''re scattered all over Orgrimmar!$b$bI''d chase after ''em myself, but this city''s so big I''d get lost for sure.$b$bCan you round ''em up for me before they float away?$b$bPlease?', `CompletedText` = 'Return to Jaga in Orgrimmar.' WHERE `entry` = 29401;
        UPDATE `quest_template` SET `Details` = 'Please, $gmister:miss;, you just gotta help me!$b$bFather bought me a bunch of balloons from the Darkmoon Faire. They''re magical, you know, and never lose their floatiness!$b$bThere''s just one thing...$b$bA gust of wind blew them out of my hands. They''re scattered all over Stormwind!$b$bI''d chase after them myself, but this city''s so big I''d get lost for sure.$b$bCan you find them for me before they float away?$b$bPlease?', `RewMoneyMaxLevel` = 960 WHERE `entry` = 29412;
